def get_connections(k, n):
    import itertools
    all_edge_sets = []
    for S in itertools.combinations(range(1, n + 1), k):
        for B in itertools.combinations(range(1, n + 1), k):
            if all(S[i] < B[i] for i in range(k)):
                edges = list(zip(S, B))
                adj = {}
                for u, v in edges:
                    if u not in adj: adj[u] = []
                    adj[u].append(v)
                connected_pairs = set()
                for start_node in range(1, n + 1):
                    reachable = set()
                    stack = [start_node]
                    while stack:
                        u = stack.pop()
                        if u in adj:
                            for v in adj[u]:
                                if v not in reachable:
                                    reachable.add(v)
                                    stack.append(v)
                    for r in reachable:
                        if r > start_node:
                            connected_pairs.add((start_node, r))
                all_edge_sets.append(connected_pairs)
    return all_edge_sets

def solve_for_n(n, k):
    all_edge_sets = get_connections(k, n)
    for i in range(len(all_edge_sets)):
        for j in range(i, len(all_edge_sets)):
            if not (all_edge_sets[i] & all_edge_sets[j]):
                return False
    return True

for n in range(3, 10):
    for k in range(1, n):
        result = solve_for_n(n, k)
        print(f"n={n}, k={k}, guaranteed={result}")

